from pathlib import Path

path = Path('src/hooks/useGame.js')
s = path.read_text()
anchor = '''Do not make NPCs fear, recognize, value, identify, counter, or understand an item or ability merely because its mechanical description appears in PLAYER DATA. Owning or equipping an item does not broadcast its stat block. An absurdly powerful weapon may simply look like an unusually fine, strange, large, or magical weapon until it actually demonstrates extraordinary power. Power does not radiate as a stat block. Do not retroactively invent rumors, prior sightings, prophetic knowledge, or specialist expertise just to justify an NPC knowing what the player can do. When uncertain, default to the NPC not knowing and let them learn through play.'''
replacement = anchor + '''\n\nPLAYER KNOWLEDGE DOES NOT SPREAD AUTOMATICALLY. A fact becoming known to the player does NOT make it known to companions, NPCs, factions, merchants, enemies, or bystanders. An NPC knows a fact only if they personally witnessed it, the player or another plausible source actually told them, their established record says they know it, or they could reasonably have learned it independently through an in-world channel. Do not silently transfer clues, discoveries, identities, plans, secrets, or conclusions from the player's perspective into an NPC's dialogue or decisions. If the player learned something in private and has not shared it, other characters remain ignorant.\n\nCAMPAIGN HISTORY IS DM MEMORY, NOT WORLDWIDE NPC MEMORY. The history/summary exists so YOU can maintain continuity; it is not a dossier every NPC has read. Do not let a newly met or unrelated NPC reference past player actions merely because those actions appear in campaign history. A secret assassination in Calimport is not automatically known to a shady merchant in Waterdeep. Distance, secrecy, witnesses, communication, reputation, elapsed time, faction intelligence, and deliberate information-sharing all matter. Public events may plausibly become rumors over time, but never invent instant notoriety, omniscient gossip, or retroactive information networks just to make an NPC aware. When knowledge provenance is unclear, the NPC does not know.'''
count = s.count(anchor)
if count < 1:
    raise SystemExit('NPC knowledge anchor not found; refusing broad edit')
s = s.replace(anchor, replacement)
path.write_text(s)
print(f'Reinforced NPC knowledge boundaries in {count} prompt location(s)')
